const now=new Date(); const day=now.getDay(); const days=(8-day)%7||7;
const start=new Date(now); start.setDate(now.getDate()+days); start.setHours(0,0,0,0);
const end=new Date(start); end.setDate(start.getDate()+7);
return [{json:{timeMin:start.toISOString(),timeMax:end.toISOString(),chatId:$env.TELEGRAM_CHAT_ID}}];

let text=$json.output_text;
if(!text&&Array.isArray($json.output)) text=$json.output.flatMap(o=>o.content||[]).map(c=>c.text||'').join('\n');
return [{json:{chatId:$('Build Weekly Prompt').first().json.chatId,text:(text||'Weekly plan generation failed.').slice(0,4000)}}];
